llm.raw_content:
{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C31"],
      "claim": "Ribavirin, the closest D-ribose carboxamide nucleoside analogue, has an absolute oral bioavailability of 44.6% in humans, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C49"],
      "claim": "Ribavirin is rapidly absorbed after oral administration with approximately 50% bioavailability in humans, reinforcing the high-F pattern for this polar carboxamide riboside.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C34"],
      "claim": "Viramidine, a closely related ribavirin analogue, shows 66.1% oral bioavailability in humans, supporting high oral bioavailability for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C08"],
      "claim": "Fludarabine, another polar nucleoside analogue, has absolute oral bioavailability of 51–55% in cancer patients, supporting F ≥ 20% for the query.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C15"],
      "claim": "Levovirin, the L-ribose isomer of ribavirin, has <10% oral bioavailability in humans, but its opposite stereochemistry reduces transferability to the D-ribose query.",
      "evidence_role": "contradictory"
    },
    {
      "card_ids": ["C30"],
      "claim": "Uridine has approximately 7% oral bioavailability in humans, but its pyrimidine dione structure is less transferable to the imidazole carboxamide query.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a D-ribose imidazole carboxamide nucleoside most closely related to ribavirin, whose human oral bioavailability is consistently ~40–50%; other polar nucleoside analogues (viramidine, fludarabine, cladribine, clofarabine) also exceed 20%. Low-bioavailability analogues are less structurally transferable (L-ribose levovirin, uridine, NHC). Therefore predict high.",
  "evidence_gaps": [
    "No direct human bioavailability measurement for the exact 5-hydroxyimidazole carboxamide riboside.",
    "The effect of the 5-hydroxy group on nucleoside transporter affinity and intestinal permeability is unknown.",
    "Potential first-pass metabolism of the query has not been directly assessed."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

